// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); vm.deal(address(this), 100 ether); }

    function testFuzz_property(uint256 ts, uint256 blk) public {
        ts = bound(ts, 1, type(uint64).max / 2);
        blk = bound(blk, 1, 100000);

        vm.warp(ts);
        vm.roll(blk);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call at the SAME timestamp: pastBlockTime must now equal ts,
        // so the timestamp check must fail and the call must revert.
        vm.roll(blk + 1);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2);
    }

    receive() external payable {}
}
